    // bootloader.version: version text of the bootloader, found in its flash (NRC 0x22 without one); always 32 bytes, a shorter value filled up with 0x00U (COM-33)
    if (values.bootSoftwareId.empty()) { return DiagReturnCode::ISO_CONDITIONS_NOT_CORRECT; }
    if (response.getAvailableDataLength() < 32U) { return DiagReturnCode::ISO_RESPONSE_TOO_LONG; }
